import{_ as a,o as t,c as l,a4 as r}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-104","description":"","frontmatter":{"date":"2021-02-23T20:24:59","title":"写作课作业-104","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/104.md","filePath":"posts/homework/104.md"}'),o={name:"posts/homework/104.md"};function h(i,e,p,n,s,c){return t(),l("div",null,[...e[0]||(e[0]=[r('<blockquote><p>《区块链小白书》之《警告、前言、准备工作》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>《区块链小白书》的目的就是为了让小白对区块链有正确且清晰的认识，让小白少走弯路，不要误入歧途。</p><p>准备工作包括三项内容：不要滥用类比，重复重复再重复，借助群智的力量。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>区块链技术上在中国获得了认可与支持，人们都区块链的误解甚至是诋毁终于可以烟消云散了。</p><p>区块链作为金融互联网新技术，不可避免地会涉及到投资和投机，市场上骗局丛生，行业里鱼龙混杂，如果没有对区块链正确且清晰的认识，容易走弯路，甚至误入歧途。</p><p>不恰当的类比被滥用多次之后，就再也没有办法形成正确的理解。</p><p>“硬着头皮读完，而后重复读很多次” 这个策略，就是可以轻松突破 “前置引用” 所设置的障碍。这个技巧，事实上可以用在任何领域。</p><p>快速掌握新知识，快速适应新领域，还有个重要的技巧，就是借助群智的力量。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>通过“<a href="http://www.xinhuanet.com/politics/2019-10/25/c_1125153665.htm" target="_blank" rel="noreferrer">新华社北京10月25日电</a>，中共中央政治局10月24日下午就区块链技术发展现状和趋势进行第十八次集体学习”的这则新闻，区块链技术上在中国获得了认可与支持，人们都区块链的误解甚至是诋毁终于可以烟消云散了。</p><p><strong>类比</strong>是约等号（≈），而“<strong>这就是</strong>”是等号（=），约等号和等号之间的差别有时甚至超过十万八千里。 多次不恰当的类比无法形成与正确理解相近的效果。</p><p>绝大多数难以理解的知识，是因为他内部有很多“前置引用”。并说明与学校学习的不同，并引用《自学是门手艺》对“前置引用”的阐述。</p><p>快速掌握新知识，快速适应新领域，还有个重要的技巧，就是借助群智的力量。1.先举例子，与学霸聊天轻松解决很多重点难点。2.说明原因，随意的交流总比刻意交流更有效。3.提供环境，定投公开课，通过提问，通过观察，很多你弄不明白的问题，可能一步小心就彻底被他人的对话解决掉了。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li><p>不恰当的类比被滥用多次之后，就再也没办法形成正确的理解。多次非常不恰当的<strong>约等于</strong>拼接起来之后，无论如何都没办法达到一个与正确理解相近的效果。</p></li><li><p>遇到暂时无法理解的概念，不要担心、不要纠结、不要停顿，你要做的事情很简单——“硬着头皮读完，而后重复读很多次”。 这个策略，就是可以轻松突破 “前置引用” 所设置的障碍。这个技巧，事实上可以用在任何领域。</p></li><li><p>快速掌握新知识，快速适应新领域，还有个重要的技巧，就是借助群智的力量。</p></li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>正确的使用类比能让我们从已知走向未知，笑来老师说要收集类比，把每个类比都当成一笔财富。只有类比收集多了，才能理解如何正确的使用类比，和使用正确的类比。</p><p>重复重复再重复，以自己的编程为例，一开始就是不懂怎么写，但是次数多了，之后就感觉之前的困难就像个窗户纸，一捅就破了，之后就不在觉得是问题了。</p><p>在践行群后花园里，有时自己是有疑问的，你会发现有人已经问了，你只要多花点时间看其他人的解答，加上你自己的思考，你会形成自己的判断，即使不说话，也能学到东西。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',29)])])}const u=a(o,[["render",h]]);export{_ as __pageData,u as default};
